//! The repository layer (09 §4.2, §9): typed row structs for every table,
//! generic insert / update / delete helpers, and the sync-class S helpers
//! that stamp `updated_at`, `rev` and `device_id` and tombstone through
//! `deleted_at`. `change_log` rows are written by the triggers of
//! `0001_initial.sql`, so every write that goes through [`create`], [`save`],
//! [`patch`], [`soft_delete`] or [`restore`] is logged without further code.
//!
//! Row structs are generated by the `table!` macro and map one-to-one onto the
//! DDL columns (booleans as `bool`, nullable columns as `Option`). The
//! `Table` trait gives each struct its table name, key columns, column list,
//! `from_row` and a by-name `value` accessor; `Syncable` marks class S tables.

use rusqlite::types::ToSql;
use rusqlite::{Connection, OptionalExtension, Row, Transaction, params_from_iter};

pub use crate::db::{DbError as Error, Result, now_rfc3339 as now};

/// A row type bound to one table.
pub trait Table: Sized {
    const TABLE: &'static str;
    /// Key column(s); `["id"]` for most tables.
    const KEY: &'static [&'static str];
    /// Every column, in DDL order.
    const COLUMNS: &'static [&'static str];
    fn from_row(r: &Row<'_>) -> rusqlite::Result<Self>;
    /// The value of one column by name, for binding.
    fn value(&self, column: &str) -> Option<&dyn ToSql>;

    /// Every column's value in [`Table::COLUMNS`] order.
    fn values(&self) -> Vec<&dyn ToSql> {
        Self::COLUMNS.iter().filter_map(|c| self.value(c)).collect()
    }

    /// The key column values.
    fn key_values(&self) -> Vec<&dyn ToSql> {
        Self::KEY.iter().filter_map(|c| self.value(c)).collect()
    }
}

/// A sync-class S row: `created_at`, `updated_at`, `rev`, `device_id`, `deleted_at`.
pub trait Syncable: Table {
    fn rev(&self) -> i64;
    fn deleted_at(&self) -> Option<&str>;
    fn stamp(&mut self, now: &str, device_id: &str, rev: i64);
    fn set_created_at(&mut self, now: &str);
    fn set_deleted_at(&mut self, at: Option<String>);
}

macro_rules! table {
    (
        $(#[$meta:meta])*
        $name:ident => $table:literal, key = [$($key:literal),+ $(,)?] {
            $( $(#[$fmeta:meta])* $field:ident : $ty:ty ),+ $(,)?
        }
    ) => {
        $(#[$meta])*
        #[derive(Debug, Clone, Default, PartialEq, ::serde::Serialize, ::serde::Deserialize)]
        pub struct $name {
            $( $(#[$fmeta])* pub $field: $ty, )+
        }

        impl $crate::repo::Table for $name {
            const TABLE: &'static str = $table;
            const KEY: &'static [&'static str] = &[$($key),+];
            const COLUMNS: &'static [&'static str] = &[$(stringify!($field)),+];

            fn from_row(r: &::rusqlite::Row<'_>) -> ::rusqlite::Result<Self> {
                Ok(Self { $( $field: r.get(stringify!($field))?, )+ })
            }

            fn value(&self, column: &str) -> Option<&dyn ::rusqlite::types::ToSql> {
                match column {
                    $( stringify!($field) => Some(&self.$field as &dyn ::rusqlite::types::ToSql), )+
                    _ => None,
                }
            }
        }
    };
}

macro_rules! syncable {
    ($name:ident) => {
        impl $crate::repo::Syncable for $name {
            fn rev(&self) -> i64 {
                self.rev
            }
            fn deleted_at(&self) -> Option<&str> {
                self.deleted_at.as_deref()
            }
            fn stamp(&mut self, now: &str, device_id: &str, rev: i64) {
                self.updated_at = now.to_string();
                self.device_id = device_id.to_string();
                self.rev = rev;
            }
            fn set_created_at(&mut self, now: &str) {
                self.created_at = now.to_string();
            }
            fn set_deleted_at(&mut self, at: Option<String>) {
                self.deleted_at = at;
            }
        }
    };
}

pub mod rows;
pub use rows::*;

/// A fresh UUID v7 (09 §4.1).
pub fn new_id() -> String {
    uuid::Uuid::now_v7().to_string()
}

/// Run `f` inside an `IMMEDIATE` transaction; commit on `Ok`, roll back on `Err`.
pub fn tx<T>(conn: &mut Connection, f: impl FnOnce(&Transaction<'_>) -> Result<T>) -> Result<T> {
    let tx = conn.transaction_with_behavior(rusqlite::TransactionBehavior::Immediate)?;
    let out = f(&tx)?;
    tx.commit()?;
    Ok(out)
}

fn placeholders(n: usize) -> String {
    (0..n).map(|_| "?").collect::<Vec<_>>().join(", ")
}

fn column_list<T: Table>() -> String {
    T::COLUMNS.join(", ")
}

fn key_where<T: Table>() -> String {
    T::KEY
        .iter()
        .map(|k| format!("{k} = ?"))
        .collect::<Vec<_>>()
        .join(" AND ")
}

fn check_columns<T: Table>(columns: &[&str]) -> Result<()> {
    for c in columns {
        if !T::COLUMNS.contains(c) {
            return Err(Error::Invalid {
                what: "column",
                detail: format!("{}.{c} does not exist", T::TABLE),
            });
        }
    }
    Ok(())
}

fn key_params<'a>(key: &[&'a dyn ToSql]) -> Vec<&'a dyn ToSql> {
    key.to_vec()
}

/// Plain insert (class L, or a class S row the caller has stamped).
/// Returns `last_insert_rowid` (the `seq` of `notes` / `messages`).
pub fn insert<T: Table>(conn: &Connection, row: &T) -> Result<i64> {
    let sql = format!(
        "INSERT INTO {} ({}) VALUES ({})",
        T::TABLE,
        column_list::<T>(),
        placeholders(T::COLUMNS.len())
    );
    conn.execute(&sql, params_from_iter(row.values()))?;
    Ok(conn.last_insert_rowid())
}

/// Insert, or update every non-conflict column when `conflict` columns collide
/// (class L rows keyed by provider ids).
pub fn upsert<T: Table>(conn: &Connection, row: &T, conflict: &[&str]) -> Result<()> {
    check_columns::<T>(conflict)?;
    let updates: Vec<String> = T::COLUMNS
        .iter()
        .filter(|c| !conflict.contains(c) && !T::KEY.contains(c))
        .map(|c| format!("{c} = excluded.{c}"))
        .collect();
    let sql = format!(
        "INSERT INTO {} ({}) VALUES ({}) ON CONFLICT({}) DO UPDATE SET {}",
        T::TABLE,
        column_list::<T>(),
        placeholders(T::COLUMNS.len()),
        conflict.join(", "),
        updates.join(", ")
    );
    conn.execute(&sql, params_from_iter(row.values()))?;
    Ok(())
}

/// Full-row `UPDATE` by key, values verbatim (class L; caller sets `updated_at`).
/// `false` when no row matched.
pub fn replace<T: Table>(conn: &Connection, row: &T) -> Result<bool> {
    let sets: Vec<String> = T::COLUMNS
        .iter()
        .filter(|c| !T::KEY.contains(c))
        .map(|c| format!("{c} = ?"))
        .collect();
    let sql = format!(
        "UPDATE {} SET {} WHERE {}",
        T::TABLE,
        sets.join(", "),
        key_where::<T>()
    );
    let mut values: Vec<&dyn ToSql> = T::COLUMNS
        .iter()
        .filter(|c| !T::KEY.contains(c))
        .filter_map(|c| row.value(c))
        .collect();
    values.extend(row.key_values());
    Ok(conn.execute(&sql, params_from_iter(values))? > 0)
}

/// Partial `UPDATE` by key, values verbatim (class L).
pub fn set_columns<T: Table>(
    conn: &Connection,
    key: &[&dyn ToSql],
    columns: &[(&str, &dyn ToSql)],
) -> Result<bool> {
    let names: Vec<&str> = columns.iter().map(|(c, _)| *c).collect();
    check_columns::<T>(&names)?;
    if columns.is_empty() {
        return Ok(false);
    }
    let sets: Vec<String> = names.iter().map(|c| format!("{c} = ?")).collect();
    let sql = format!(
        "UPDATE {} SET {} WHERE {}",
        T::TABLE,
        sets.join(", "),
        key_where::<T>()
    );
    let mut values: Vec<&dyn ToSql> = columns.iter().map(|(_, v)| *v).collect();
    values.extend(key_params(key));
    Ok(conn.execute(&sql, params_from_iter(values))? > 0)
}

/// One row by key.
pub fn get<T: Table>(conn: &Connection, key: &[&dyn ToSql]) -> Result<Option<T>> {
    let sql = format!(
        "SELECT {} FROM {} WHERE {}",
        column_list::<T>(),
        T::TABLE,
        key_where::<T>()
    );
    Ok(conn
        .query_row(&sql, params_from_iter(key_params(key)), T::from_row)
        .optional()?)
}

/// One row by its single-column key.
pub fn get_by_id<T: Table>(conn: &Connection, id: &str) -> Result<Option<T>> {
    get::<T>(conn, &[&id])
}

/// One row by its single-column key, or [`Error::NotFound`].
pub fn must_get<T: Table>(conn: &Connection, id: &str) -> Result<T> {
    get_by_id::<T>(conn, id)?.ok_or_else(|| Error::NotFound {
        table: T::TABLE,
        key: id.to_string(),
    })
}

/// Rows matching `where_sql` (which may carry `ORDER BY` / `LIMIT`); `"1"` for all.
pub fn query<T: Table>(
    conn: &Connection,
    where_sql: &str,
    params: &[&dyn ToSql],
) -> Result<Vec<T>> {
    let sql = format!(
        "SELECT {} FROM {} WHERE {}",
        column_list::<T>(),
        T::TABLE,
        where_sql
    );
    let mut stmt = conn.prepare(&sql)?;
    let rows = stmt.query_map(params_from_iter(key_params(params)), T::from_row)?;
    Ok(rows.collect::<rusqlite::Result<Vec<T>>>()?)
}

/// `COUNT(*)` of rows matching `where_sql`.
pub fn count<T: Table>(conn: &Connection, where_sql: &str, params: &[&dyn ToSql]) -> Result<i64> {
    let sql = format!("SELECT COUNT(*) FROM {} WHERE {}", T::TABLE, where_sql);
    Ok(conn.query_row(&sql, params_from_iter(key_params(params)), |r| r.get(0))?)
}

/// Hard delete by key (class L, or purging a class S tombstone).
pub fn delete<T: Table>(conn: &Connection, key: &[&dyn ToSql]) -> Result<bool> {
    let sql = format!("DELETE FROM {} WHERE {}", T::TABLE, key_where::<T>());
    Ok(conn.execute(&sql, params_from_iter(key_params(key)))? > 0)
}

/// Hard delete by single-column key.
pub fn delete_by_id<T: Table>(conn: &Connection, id: &str) -> Result<bool> {
    delete::<T>(conn, &[&id])
}

// ---------------------------------------------------------------------------
// Sync-class S helpers: every write stamps updated_at / rev / device_id (09 §4.2).
// ---------------------------------------------------------------------------

/// Insert a new class S row: `created_at = updated_at = now`, `rev = 1`,
/// `device_id = local`, `deleted_at = NULL`. The insert trigger logs it.
pub fn create<T: Syncable>(conn: &Connection, device_id: &str, row: &mut T) -> Result<i64> {
    let now = now();
    row.set_created_at(&now);
    row.stamp(&now, device_id, 1);
    row.set_deleted_at(None);
    insert(conn, row)
}

/// Full-row update of a class S row with `rev + 1`, `updated_at = now`,
/// `device_id = local`. The row struct is stamped in place.
pub fn save<T: Syncable>(conn: &Connection, device_id: &str, row: &mut T) -> Result<()> {
    let now = now();
    let rev = row.rev() + 1;
    row.stamp(&now, device_id, rev);
    if !replace(conn, row)? {
        return Err(Error::NotFound {
            table: T::TABLE,
            key: "(row key)".into(),
        });
    }
    Ok(())
}

/// Partial update of a live class S row by id, stamped. `false` when the row
/// is missing or tombstoned.
pub fn patch<T: Syncable>(
    conn: &Connection,
    device_id: &str,
    id: &str,
    columns: &[(&str, &dyn ToSql)],
) -> Result<bool> {
    let names: Vec<&str> = columns.iter().map(|(c, _)| *c).collect();
    check_columns::<T>(&names)?;
    for reserved in ["rev", "updated_at", "device_id", "deleted_at"] {
        if names.contains(&reserved) {
            return Err(Error::Invalid {
                what: "column",
                detail: format!("{reserved} is stamped by the repository, not patched"),
            });
        }
    }
    let now = now();
    let mut sets: Vec<String> = names.iter().map(|c| format!("{c} = ?")).collect();
    sets.push("rev = rev + 1".into());
    sets.push("updated_at = ?".into());
    sets.push("device_id = ?".into());
    let sql = format!(
        "UPDATE {} SET {} WHERE {} AND deleted_at IS NULL",
        T::TABLE,
        sets.join(", "),
        key_where::<T>()
    );
    let mut values: Vec<&dyn ToSql> = columns.iter().map(|(_, v)| *v).collect();
    values.push(&now);
    values.push(&device_id);
    values.push(&id);
    Ok(conn.execute(&sql, params_from_iter(values))? > 0)
}

/// Tombstone a live class S row (`deleted_at = now`, stamped). `false` when
/// already deleted or missing. The update trigger logs a `delete`.
pub fn soft_delete<T: Syncable>(conn: &Connection, device_id: &str, id: &str) -> Result<bool> {
    let now = now();
    let sql = format!(
        "UPDATE {} SET deleted_at = ?, updated_at = ?, rev = rev + 1, device_id = ? WHERE {} AND deleted_at IS NULL",
        T::TABLE,
        key_where::<T>()
    );
    Ok(conn.execute(&sql, rusqlite::params![now, now, device_id, id])? > 0)
}

/// Un-tombstone a class S row, stamped. `false` when not tombstoned or missing.
pub fn restore<T: Syncable>(conn: &Connection, device_id: &str, id: &str) -> Result<bool> {
    let now = now();
    let sql = format!(
        "UPDATE {} SET deleted_at = NULL, updated_at = ?, rev = rev + 1, device_id = ? WHERE {} AND deleted_at IS NOT NULL",
        T::TABLE,
        key_where::<T>()
    );
    Ok(conn.execute(&sql, rusqlite::params![now, device_id, id])? > 0)
}

/// Hard delete a class S row; the delete trigger logs it only when it was live.
pub fn purge<T: Syncable>(conn: &Connection, id: &str) -> Result<bool> {
    delete_by_id::<T>(conn, id)
}

/// A live (not tombstoned) class S row by id.
pub fn get_live<T: Syncable>(conn: &Connection, id: &str) -> Result<Option<T>> {
    let sql = format!(
        "SELECT {} FROM {} WHERE {} AND deleted_at IS NULL",
        column_list::<T>(),
        T::TABLE,
        key_where::<T>()
    );
    Ok(conn.query_row(&sql, [id], T::from_row).optional()?)
}

/// Every live class S row, ordered by `order_sql` (a column list, e.g. `"position, name"`).
pub fn list_live<T: Syncable>(conn: &Connection, order_sql: &str) -> Result<Vec<T>> {
    query::<T>(
        conn,
        &format!("deleted_at IS NULL ORDER BY {order_sql}"),
        &[],
    )
}

/// Normalize a tag name (09 §5.1 `name_norm`): lowercase, trimmed, internal
/// whitespace collapsed to one space.
pub fn normalize_tag(name: &str) -> String {
    name.split_whitespace()
        .collect::<Vec<_>>()
        .join(" ")
        .to_lowercase()
}
